function describeValidationErrors(errors: ErrorObject[] | null | undefined): string[] {
  if (!errors || errors.length === 0) return ['input does not match schema'];
  return errors.map(err => formatValidationError(err as SchemaError));
}

function formatValidationError(err: SchemaError): string {
  const basePath = toDotPath(err);
  if (err.keyword === 'required') {
    const missing = String((err.params as {missingProperty?: unknown}).missingProperty ?? '');
    const fullPath = basePath ? `${basePath}.${missing}` : missing;
    return `${fullPath} is required`;
  }
  const target = basePath || 'input';
  if (err.keyword === 'type') {
    const expectedType = String((err.params as {type?: unknown}).type ?? '');
    return `${target} must be ${expectedType}`;
  }
  return `${target} ${err.message ?? `failed ${err.keyword} check`}`;
}

